import java.sql.SQLException;
import java.util.Optional;

/**
 * 公告表数据访问。
 */
@Repository
public class CampaignRepository {

    private final JdbcTemplate jdbc;

    public CampaignRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    private static final RowMapper<Campaign> MAPPER = new RowMapper<>() {
        @Override
        public Campaign mapRow(ResultSet rs, int rowNum) throws SQLException {
            return new Campaign(
                    rs.getString("campaign_id"),
                    rs.getInt("daily_total_cap"),
                    rs.getInt("per_visitor_daily_cap"),
                    rs.getInt("cooldown_minutes"),
                    rs.getLong("version"),
                    rs.getLong("created_at_utc"));
        }
    };

    private static final String COLUMNS =
            "campaign_id, daily_total_cap, per_visitor_daily_cap, cooldown_minutes, version, created_at_utc";

    /**
     * 按编号查询公告。
     */
    public Optional<Campaign> findById(String campaignId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM campaign WHERE campaign_id = ?", MAPPER, campaignId)
                .stream()
                .findFirst();
    }

    /**
     * 插入公告；编号冲突由调用方依据唯一约束处理。新版本号从 0 起。
     */
    public void insert(Campaign campaign) {
        jdbc.update("INSERT INTO campaign (" + COLUMNS + ") VALUES (?, ?, ?, ?, ?, ?)",
                campaign.campaignId(),
                campaign.dailyTotalCap(),
                campaign.perVisitorDailyCap(),
                campaign.cooldownMinutes(),
                campaign.version(),
                campaign.createdAtUtc());
    }

    /**
     * 乐观锁更新冷却分钟数：仅当当前版本等于 expectedVersion 时更新并将版本 +1。
     *
     * @return 是否更新成功；false 表示版本冲突（或公告不存在）
     */
    public boolean updateCooldown(String campaignId, int cooldownMinutes, long expectedVersion) {
        int rows = jdbc.update("UPDATE campaign SET cooldown_minutes = ?, version = version + 1 "
                        + "WHERE campaign_id = ? AND version = ?",
                cooldownMinutes, campaignId, expectedVersion);
        return rows == 1;
    }
}

package com.example.starter.exposure.repo;

import com.example.starter.exposure.domain.VisitorCooldown;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Optional;

/**
 * 访客冷却状态数据访问。加锁方法必须在事务内调用。
 */
@Repository
public class CooldownRepository {

    private static final RowMapper<VisitorCooldown> MAPPER = (rs, rowNum) -> new VisitorCooldown(
            rs.getString("campaign_id"),
            rs.getString("visitor_id"),
            rs.getLong("last_confirmed_at_utc"));

    private final JdbcTemplate jdbc;

    public CooldownRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** 查询访客对公告的冷却状态；无行表示从未确认。 */
    public Optional<VisitorCooldown> find(String campaignId, String visitorId) {
        List<VisitorCooldown> list = jdbc.query(
                "SELECT campaign_id, visitor_id, last_confirmed_at_utc "
                        + "FROM visitor_campaign_cooldown WHERE campaign_id = ? AND visitor_id = ?",
                MAPPER, campaignId, visitorId);
        return list.stream().findFirst();
    }

    /**
     * 行锁查询冷却状态，用于申请阶段与并发确认互斥；无行表示从未确认。
     */
    public Optional<VisitorCooldown> lockForUpdate(String campaignId, String visitorId) {
        List<VisitorCooldown> list = jdbc.query(
                "SELECT campaign_id, visitor_id, last_confirmed_at_utc "
                        + "FROM visitor_campaign_cooldown WHERE campaign_id = ? AND visitor_id = ? FOR UPDATE",
                MAPPER, campaignId, visitorId);
        return list.stream().findFirst();
    }

    /**
     * 插入或更新最近确认时刻（确认成功时调用，同事务）。
     */
    public void upsertLastConfirmed(String campaignId, String visitorId, long confirmedAtUtc) {
        int rows = jdbc.update("UPDATE visitor_campaign_cooldown SET last_confirmed_at_utc = ? "
                        + "WHERE campaign_id = ? AND visitor_id = ?",
                confirmedAtUtc, campaignId, visitorId);
        if (rows == 0) {
            jdbc.update("INSERT INTO visitor_campaign_cooldown "
                            + "(campaign_id, visitor_id, last_confirmed_at_utc) VALUES (?, ?, ?)",
                    campaignId, visitorId, confirmedAtUtc);
        }
    }
}

