    }

    @Test
    @DisplayName("冷却只拦截申请：已存在 RESERVED 的确认与取消不受影响")
    void cooldown_doesNotAffectExistingReservedConfirmCancel() {
        createCampaign("req-c1", "c1", 10, 10, 30);
        ReservationResponse r1 = applyAndConfirm("req-1", "c1", "v1");
        assertEquals("CONFIRMED", r1.status().name());

        // 另一访客确认后，其新申请被冷却拦截；但本访客此前已存在的预占仍可确认
        createCampaign("req-c2", "c2", 10, 10, 60);
        ReservationResponse existing = service.apply(new ApplyExposureRequest("req-2-a", "c2", "v9"));
        applyAndConfirm("req-3", "c2", "v8");
