        assertEquals(2, day1.get(1).seqNo());
        assertEquals(new BigDecimal("0.5000"), day1.get(1).decayWeight());
        assertEquals(3, day1.get(2).seqNo());
        assertEquals(new BigDecimal("0.3333"), day1.get(2).decayWeight());

        // 跨零点：重新从 1 计数
