        // 失败（版本冲突）不占键：修正参数后同键可成功
        assert409(() -> service.updateCooldown("c1", new UpdateCooldownRequest("key-f", 30, 0L)));
        CampaignResponse retried = service.updateCooldown("c1",
                new UpdateCooldownRequest("key-f", 30, 1L));
